const stdout = $input.first().json.stdout || '';
const lines = stdout.split('\n');

// Find the JSON output from the pipeline
let policyResult = null;
for (const line of lines) {
  try {
    const parsed = JSON.parse(line);
    if (parsed.overall_status) {
      policyResult = parsed;
      break;
    }
  } catch (e) {}
}

// Fall back to reading the output file
if (!policyResult) {
  const fs = require('fs');
  const files = fs.readdirSync('/tmp');
  const resultFile = files.find(f => f.endsWith('.policy_result.json'));
  if (resultFile) {
    policyResult = JSON.parse(fs.readFileSync('/tmp/' + resultFile, 'utf8'));
  }
}

return [{ json: { policy_result: policyResult, pdf_path: $('1. Pitch Deck Submitted').first().json.body.pdf_path, analyst_email: $('1. Pitch Deck Submitted').first().json.body.analyst_email } }];

// This node checks whether the analyst approved or rejected
const decision = $input.first().json.body?.decision || 'approved';
const notes = $input.first().json.body?.notes || '';

if (decision !== 'approved') {
  throw new Error('Analyst rejected this opportunity. Workflow stopped.');
}

return [{ json: { ...$('3. Parse Policy Result').first().json, decision, analyst_notes: notes } }];
